const particles = Array.from({ length: 46 }, (_, index) => ({ id: index, left: (index * 37 + 11) % 100, size: 2 + (index % 5) * 1.4, delay: -((index * 1.7) % 14), duration: 9 + (index % 7) * 1.55 }));
const deepLife = Array.from({ length: 13 }, (_, index) => ({ id: index, left: 7 + ((index * 31) % 86), top: 12 + ((index * 47) % 72), scale: .65 + (index % 5) * .18, delay: (index % 7) * .24 }));

